-- Performance measurements on 100,000 requests (see docs/performance.md).
-- Run: sqlcmd -S localhost -E -C -d RequestsManagement -i database\performance-queries.sql
-- Each query is the SQL generated by EF Core for the matching API call (OFFSET/FETCH page of 20).
-- Add "SET STATISTICS XML ON" (or Ctrl+M in SSMS) to see the actual execution plan.
SET NOCOUNT ON;
SET STATISTICS IO ON;
SET STATISTICS TIME ON;

PRINT '--- Q1: GET /api/requests default (no filter, CreatedAt DESC) ---';
SELECT r.Id, r.Title, r.OrganizationName, r.Status, r.Priority, r.AssignedToUserId, r.CreatedAt, r.UpdatedAt, r.RowVersion
FROM Requests r ORDER BY r.CreatedAt DESC, r.Id OFFSET 0 ROWS FETCH NEXT 20 ROWS ONLY;
SELECT COUNT(*) FROM Requests;

PRINT '--- Q2: filter Status + Priority + date range ---';
SELECT r.Id, r.Title, r.OrganizationName, r.Status, r.Priority, r.AssignedToUserId, r.CreatedAt, r.UpdatedAt, r.RowVersion
FROM Requests r
WHERE r.Status = 1 AND r.Priority = 2 AND r.CreatedAt >= '2025-01-01' AND r.CreatedAt < '2027-01-01'
ORDER BY r.CreatedAt DESC, r.Id OFFSET 0 ROWS FETCH NEXT 20 ROWS ONLY;
SELECT COUNT(*) FROM Requests r
WHERE r.Status = 1 AND r.Priority = 2 AND r.CreatedAt >= '2025-01-01' AND r.CreatedAt < '2027-01-01';

PRINT '--- Q3: organization prefix (LIKE ''Acme Branch 11%'') ---';
SELECT r.Id, r.Title, r.OrganizationName, r.CreatedAt
FROM Requests r WHERE r.OrganizationName LIKE N'Acme Branch 11%' ESCAPE N'\'
ORDER BY r.CreatedAt DESC, r.Id OFFSET 0 ROWS FETCH NEXT 20 ROWS ONLY;

PRINT '--- Q4: free text search (LIKE ''%issue #7777%'') ---';
SELECT r.Id, r.Title, r.OrganizationName, r.CreatedAt
FROM Requests r
WHERE r.Title LIKE N'%issue #7777%' ESCAPE N'\' OR r.OrganizationName LIKE N'%issue #7777%' ESCAPE N'\'
ORDER BY r.CreatedAt DESC, r.Id OFFSET 0 ROWS FETCH NEXT 20 ROWS ONLY;
SELECT COUNT(*) FROM Requests r
WHERE r.Title LIKE N'%issue #7777%' ESCAPE N'\' OR r.OrganizationName LIKE N'%issue #7777%' ESCAPE N'\';

PRINT '--- Q5: deep page (page 4000, OFFSET 79980) ---';
SELECT r.Id, r.Title, r.OrganizationName, r.CreatedAt
FROM Requests r ORDER BY r.CreatedAt DESC, r.Id OFFSET 79980 ROWS FETCH NEXT 20 ROWS ONLY;

PRINT '--- Q6: summary aggregations ---';
SELECT Status, COUNT(*) FROM Requests GROUP BY Status;
SELECT Priority, COUNT(*) FROM Requests GROUP BY Priority;
